import{_ as o,o as i,c as a,a5 as l}from"./chunks/framework.DrDMl0tG.js";const u=JSON.parse('{"title":"Changelog: v2.0 – v2.3","description":"","frontmatter":{},"headers":[],"relativePath":"sections/changelog/v2.0-2.3.md","filePath":"sections/changelog/v2.0-2.3.md"}'),s={name:"sections/changelog/v2.0-2.3.md"};function t(d,e,r,c,n,p){return i(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="changelog-v2-0-v2-3" tabindex="-1">Changelog: v2.0 – v2.3 <a class="header-anchor" href="#changelog-v2-0-v2-3" aria-label="Permalink to &quot;Changelog: v2.0 – v2.3&quot;">​</a></h1><h2 id="v2-3-0-2026-05-28" tabindex="-1">v2.3.0 (2026-05-28) <a class="header-anchor" href="#v2-3-0-2026-05-28" aria-label="Permalink to &quot;v2.3.0 (2026-05-28)&quot;">​</a></h2><ul><li>Rolling and spinning friction per material pair (opt-in; XML <code>rolling_friction</code>/<code>spinning_friction</code>).</li><li>Camera lens model: pinhole or equidistant fisheye with intrinsics (<code>CameraLens.hpp</code>); <code>Sensor::setAttachmentFrame</code>; depth point clouds use NaN for misses.</li><li>Visual-only heightmap updates (<code>updateVisualHeight</code>, <code>updateVisualHeightPatch</code>, <code>setColorPatch</code>).</li><li><code>Object::getRenderRevision</code>; <code>DeformableObject::applyRigidTransform</code>; <code>World::loadMjcfFile</code>.</li><li>Failed CoACD falls back to a convex hull.</li><li>Server sim control: pause/resume/step, force, torque, pose and GC requests; <code>integrateWorldThreadSafe(beforeStep)</code>.</li><li>Server binds to loopback by default; port fallback; UDP discovery beacon.</li><li>TCP viewer: sim control, robot inspector, measuring tools, X-ray, standard views, screenshots, weather panel.</li><li>rayrai: weather presets, rain/snow, physical sky, clouds, fog volumes.</li><li>rayrai post-processing: MSAA, TAA, upscaling, bloom, SSAO, SSR, OIT, auto exposure, tone mapping and many lens/stylized effects.</li><li>rayrai lighting: shadow cascades, shadowed point/spot lights, reflection probes, irradiance volumes, decals.</li><li>rayrai materials: sheen, anisotropy, transmission, clearcoat, parallax, foliage; <code>Material</code> factories; <code>PbrEnvironment</code>.</li><li>rayrai: shader binary cache and prewarming, multithreaded offscreen rendering, retuned presets, diagnostics.</li><li>Build: <code>RAISIM_OPENUSD</code>, ARM detection, Windows OpenUSD; docs split into topic pages.</li></ul><h2 id="v2-2-0-2026-05-06" tabindex="-1">v2.2.0 (2026-05-06) <a class="header-anchor" href="#v2-2-0-2026-05-06" aria-label="Permalink to &quot;v2.2.0 (2026-05-06)&quot;">​</a></h2><ul><li>Deformable objects (XPBD cloth and soft bodies): <code>addDeformableCloth</code>, <code>addDeformableObject</code>.</li><li>Granular media (DEM): <code>addGranularParticles</code>, <code>addGranularBox</code>, emitters, boundaries, coupling with all bodies.</li><li><code>ArticulatedSystem::solveIK</code>.</li><li>Swept CCD for fast primitives (opt-in).</li><li>Stable object IDs, collision filter/material setters, single-body snapshot/restore/clone.</li><li><code>World::captureDepthCamera</code> (CPU depth/segmentation).</li><li>Mesh asset pipeline (<code>preprocessMesh</code>, OBJ cache, <code>exportMeshAssetsToObj</code>); USD mesh colliders with bundled OpenUSD.</li><li>MJCF <code>meshdir</code> and Menagerie models.</li><li>Faster plane, heightmap-mesh, sphere and Jacobian paths; solver skips zero impulses.</li><li><strong>Behaviour change:</strong> <code>VISUALIZER</code> sensor source removed (RGB/depth default to <code>MANUAL</code>); <code>RaisimServer::setMap</code> removed.</li><li>Server streams deformables, granular particles and point clouds; protocol 10021 with feature negotiation.</li><li>Fixes: material updates, wires removed with objects, relative mesh paths, XML, matrix helpers, ray lists.</li><li>rayrai: quality presets, HDR IBL, reflection probes, bloom, SSAO, DOF, extra lights, glTF materials, async mesh loading and readback, instanced LOD.</li><li>New asset, USD and rayrai examples; standalone visualizer build.</li></ul><h2 id="v2-1-0-2026-04-26" tabindex="-1">v2.1.0 (2026-04-26) <a class="header-anchor" href="#v2-1-0-2026-04-26" aria-label="Permalink to &quot;v2.1.0 (2026-04-26)&quot;">​</a></h2><ul><li>CoACD convex decomposition (<code>MeshCollisionMode::CONVEXIFY</code>, <code>CoacdOptions</code>), default for <code>addMesh</code>, cached on disk.</li><li>rayrai PBR shading of glTF/Assimp materials with soft shadows.</li><li><code>rayrai_coacd_mesh_approximation</code> example.</li><li>Linux ARM64 rayrai; Linux x86_64/arm64 and Windows packages.</li></ul><h2 id="v2-0-1-2026-04-25" tabindex="-1">v2.0.1 (2026-04-25) <a class="header-anchor" href="#v2-0-1-2026-04-25" aria-label="Permalink to &quot;v2.0.1 (2026-04-25)&quot;">​</a></h2><ul><li><code>World::addHeightMap</code> is fast again (bounds and tiles only).</li><li>Linux/Windows install script updates.</li></ul><h2 id="v2-0-0-2026-02-15" tabindex="-1">v2.0.0 (2026-02-15) <a class="header-anchor" href="#v2-0-0-2026-02-15" aria-label="Permalink to &quot;v2.0.0 (2026-02-15)&quot;">​</a></h2><ul><li>New built-in collision detection replaces ODE (GJK/EPA, MPR, primitive pairs, mesh and heightmap contacts).</li><li>Broadphase choice (SAP, MBP, none) via <code>setContactSettings</code>/<code>setBroadphaseSettings</code>.</li><li>Sleeping islands (on by default) with <code>setSleeping*</code>, <code>wakeObject</code>, <code>isObjectSleeping</code>.</li><li><code>integrateNoContactDetection</code>; <code>rayTestLidar</code>; <strong>breaking:</strong> <code>rayTest</code> drops <code>closestOnly</code>.</li><li>Any Assimp mesh format; <code>MeshCollisionMode</code> (convex hull default); <code>convexifyCollisionMeshes</code>.</li><li><code>CollisionBodyHandle</code> replaces <code>dGeomID</code>; <code>setCollisionBody*</code> renames; self-collision helpers.</li><li>Faster bounding boxes, Jacobians, stepping and material lookup.</li><li>Fixes: pin-constraint contact indices, capsule tunnelling, mesh/heightmap contact stability, <code>Ground::setPosition</code>.</li><li><strong>Behaviour change:</strong> contact <code>erp</code> 0.3 → 1.5; XML ground collision group 31 → 63.</li><li><code>SpinningLidar</code> sensor; <code>SensorSet</code>; sensor XML references in URDF; depth-camera row and NaN fixes.</li><li>URDF modules; ordered XML template parameters.</li><li>Server: point clouds, <code>InstancedVisuals::setScale</code>, faster reconnect.</li><li><code>lock()</code>/<code>unlock()</code> on world objects; printf-style logging macros.</li><li>rayrai renderer and <code>RaisimTcpViewer</code>.</li><li>System Eigen required; Clang 20; Windows support; Dockerfile.</li></ul>',11)])])}const m=o(s,[["render",t]]);export{u as __pageData,m as default};
